mapper.select:
SELECT l.id, u.nickname, l.action, l.target_type, l.target_id, l.target_label, l.detail, l.result, l.created_at FROM admin_logs l LEFT JOIN users u ON u.id = l.admin_id
AND (u.nickname LIKE CONCAT('%', #{q}, '%') OR l.target_label LIKE CONCAT('%', #{q}, '%') OR l.target_id = #{q})
AND l.target_type IN #{t}
AND l.created_at >= #{since}
ORDER BY l.id DESC LIMIT #{limit}
